message.content:
The bug is a data race on `c.count`.

- `c.count++` is not atomic: it performs a read, an increment, and a write.
- Multiple goroutines can read the same value at the same time and then write back the same incremented value, causing lost increments.
- `GetCount()` also reads `c.count` without synchronization, so it is part of the race too.
- `sync.WaitGroup` only ensures `main` waits until all goroutines finish; it does not make the shared counter access safe.

Fix: protect `count` with a mutex.

<solution language="go" verdict="fix">
package main

import (
    "fmt"
    "sync"
)

type Counter struct {
    mu    sync.Mutex
    count int
}

func (c *Counter) Increment() {
    c.mu.Lock()
    defer c.mu.Unlock()
    c.count++
}

func (c *Counter) GetCount() int {
    c.mu.Lock()
    defer c.mu.Unlock()
    return c.count
}

func main() {
    counter := &Counter{}
    var wg sync.WaitGroup

    for i := 0; i < 1000; i++ {
        wg.Add(1)
        go func() {
            defer wg.Done()
            counter.Increment()
        }()
    }

    wg.Wait()
    fmt.Println("Final count:", counter.GetCount())
}
</solution>

